"""Lexicographic periodic shortest lineages and independent artifact auditing."""
import heapq
from exactcal import calibrate, valid_calibration, valid_cycle
from exactfabric import Calendar


def envelope(cal, guard, witnesses=False):
    cal.build_graph()
    size, n, radix = cal.size, cal.n, cal.radix
    labels = [None] * size
    pred = [None] * size if witnesses else None
    heap = [(0, v) for v in cal.sources]
    heapq.heapify(heap)
    for v in cal.sources:
        labels[v] = 0
    pop, push = heapq.heappop, heapq.heappush
    adj, waiting = cal.adj, cal.wait_encoded
    while heap:
        dist, v = pop(heap)
        if labels[v] != dist:
            continue
        dest = v + n
        if dest >= size:
            dest -= size
        candidate = dist + waiting[v]
        old = labels[dest]
        if old is None or candidate < old:
            labels[dest] = candidate
            if witnesses:
                pred[dest] = [v, -1]
            push(heap, (candidate, dest))
        edges = adj[v]
        if edges is not None:
            for dest, weight, code, margin in edges:
                if guard > margin:
                    continue
                candidate = dist + weight
                old = labels[dest]
                if old is None or candidate < old:
                    labels[dest] = candidate
                    if witnesses:
                        pred[dest] = [v, code]
                    push(heap, (candidate, dest))
    peak = 0
    for v, label in enumerate(labels):
        if label is None:
            return None, labels, pred
        peak = max(peak, label // radix + cal.wait[v])
    return peak, labels, pred


def objectives(cal, witnesses=False):
    peaks = []
    guard = None
    selected_labels = None
    selected_pred = None
    for setting in cal.fabric['guards_ns']:
        peak, labels, pred = envelope(cal, setting, witnesses and guard is None)
        peaks.append(peak)
        if guard is None and peak is not None and setting * 1000000000 >= peak + cal.fabric['reconfig_ns'] * 1000000000:
            guard = setting
            selected_labels = labels
            selected_pred = pred
    return peaks, guard, selected_labels, selected_pred


def warmup(cal, labels):
    k = 0
    for v, label in enumerate(labels):
        age = label % cal.radix
        phase = v // cal.n
        k = max(k, (age - phase + cal.p - 1) // cal.p)
    return k


def compile_plan(profile, fabric):
    calibration = calibrate(profile)
    if calibration['status'] == 'inconsistent':
        return calibration
    cal = Calendar(profile, fabric, calibration)
    peaks, guard, labels, pred = objectives(cal, True)
    result = {'status': 'ok', 'profile': calibration, 'period_rounds': cal.p,
              'peaks_as': peaks, 'guard_ns': guard, 'bounds_as': None,
              'age_rounds': None, 'pred': None, 'warmup_cycle': None}
    if guard is not None:
        bounds = [label // cal.radix for label in labels]
        ages = [label % cal.radix for label in labels]
        result['bounds_as'] = [bounds[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['age_rounds'] = [ages[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['pred'] = [pred[i:i + cal.n] for i in range(0, cal.size, cal.n)]
        result['warmup_cycle'] = warmup(cal, labels)
    return result


def same_integer(a, b):
    return type(a) is int and a == b


def same_nullable_integer(a, b):
    return a is None if b is None else same_integer(a, b)


def check_plan(profile, fabric, proposal):
    # Inconsistency is a self-contained proof, with no dependence on the
    # compiler's choice of negative cycle.
    if proposal['status'] == 'inconsistent':
        return valid_cycle(profile, proposal)
    calibration = calibrate(profile)
    if calibration['status'] != 'ok':
        return False
    if not valid_calibration(profile, proposal['profile'], calibration):
        return False
    cal = Calendar(profile, fabric, calibration)
    if not same_integer(proposal['period_rounds'], cal.p):
        return False
    peaks, guard, labels, _ = objectives(cal)
    if len(proposal['peaks_as']) != len(peaks) or any(not same_nullable_integer(a, b) for a, b in zip(proposal['peaks_as'], peaks)):
        return False
    if not same_nullable_integer(proposal['guard_ns'], guard):
        return False
    if guard is None:
        return all(proposal[key] is None for key in ('bounds_as', 'age_rounds', 'pred', 'warmup_cycle'))
    if not same_integer(proposal['warmup_cycle'], warmup(cal, labels)):
        return False
    matrices = [proposal[key] for key in ('bounds_as', 'age_rounds', 'pred')]
    if any(matrix is None or len(matrix) != cal.p or any(len(row) != cal.n for row in matrix) for matrix in matrices):
        return False
    bounds, ages, pred = ([cell for row in matrix for cell in row] for matrix in matrices)
    for v, label in enumerate(labels):
        if label is None:
            if bounds[v] is not None or ages[v] is not None or pred[v] is not None:
                return False
        elif not same_integer(bounds[v], label // cal.radix) or not same_integer(ages[v], label % cal.radix):
            return False
    # Labels are compared with independently computed optima, while witnesses
    # are checked as actual steps, never compared with a chosen shortest tree.
    for v, label in enumerate(labels):
        if label is None or cal.anchors[v]:
            if pred[v] is not None:
                return False
            continue
        step = pred[v]
        if not isinstance(step, list) or len(step) != 2:
            return False
        prev, kind = step
        if type(prev) is not int or not 0 <= prev < cal.size or type(kind) is not int:
            return False
        if labels[prev] is None:
            return False
        phase, src_node = divmod(prev, cal.n)
        dest_phase, dest_node = divmod(v, cal.n)
        if kind == -1:
            if dest_node != src_node or dest_phase != (phase + 1) % cal.p:
                return False
            weight = cal.wait_encoded[prev]
        else:
            if not 0 <= kind < len(cal.directions):
                return False
            src, dst, _, _, _, rounds, hop, _, _, _ = cal.directions[kind]
            if src != src_node or dst != dest_node or dest_phase != (phase + rounds) % cal.p:
                return False
            if not cal.eligible(phase, kind, guard):
                return False
            weight = (hop + cal.aging(phase, kind)) * cal.radix + rounds
        if label != labels[prev] + weight:
            return False
    return True


def audit(profile, fabric, proposal):
    # Union alternatives of a well-typed artifact may still be semantically
    # incompatible (for example a null matrix with a claimed finite guard).
    try:
        return {'valid': bool(check_plan(profile, fabric, proposal))}
    except (KeyError, TypeError, IndexError, ValueError):
        return {'valid': False}
