"""Packet snapshots, clock incarnations and boundary-ordered exact replay."""
from exactcal import calibrate
from exactfabric import Calendar


def replay(profile, fabric, guard, trace):
    calibration = calibrate(profile)
    if calibration['status'] != 'ok':
        return calibration
    cal = Calendar(profile, fabric, calibration)
    n, p, t = cal.n, cal.p, cal.t
    r = trace['rounds']
    actual = trace['rates_ppb']
    bias = trace['bias_ps']
    errors = [None] * n
    bounds = [None] * n
    generations = [0] * n
    sends_at = [[] for _ in range(r + 1)]
    sends = trace['sends']
    for idx in sorted(range(len(sends)), key=lambda i: sends[i][0]):
        sends_at[sends[idx][1]].append(idx)
    reboot_at = [[] for _ in range(r + 1)]
    for tick, node in trace['reboots']:
        reboot_at[tick].append(node)
    due = [[] for _ in range(r + 1)]
    query_ticks = set(trace['queries'])
    query_states = {}
    statuses = [None] * len(sends)
    lost = set(trace['lost'])
    delivered = adopted = unknown = stale = pending = 0
    peak = 0
    always_known = True

    for tick in range(r + 1):
        phase = tick % p
        if tick:
            prevphase = (tick - 1) % p
            signed = actual[tick - 1]
            for i in range(n):
                if errors[i] is not None:
                    errors[i] += signed[i] * t
                    bounds[i] += cal.rates[i][prevphase] * t
                    peak = max(peak, abs(errors[i]))
        for i in reboot_at[tick]:
            generations[i] += 1
            errors[i] = bounds[i] = None
        for i in cal.anchor_nodes[phase]:
            errors[i] = bounds[i] = 0
        adopted_here = [None] * n
        best = {}
        delivered += len(due[tick])
        for src, dst, sg, dg, error, bound, packet_id in due[tick]:
            if generations[src] != sg or generations[dst] != dg:
                stale += 1
            elif error is None:
                unknown += 1
            else:
                candidate = (bound, packet_id, error)
                if dst not in best or candidate[:2] < best[dst][:2]:
                    best[dst] = candidate
        for dst, (bound, packet_id, error) in best.items():
            if bounds[dst] is None or bound < bounds[dst]:
                bounds[dst] = bound
                errors[dst] = error
                adopted_here[dst] = packet_id
                adopted += 1
        # Release delivered snapshot storage, not the clocks it has supplied.
        due[tick] = None
        for error in errors:
            if error is None:
                always_known = False
            else:
                peak = max(peak, abs(error))
        if tick in query_ticks:
            query_states[tick] = {'bounds_as': bounds.copy(), 'errors_as': errors.copy(),
                                  'adopted': adopted_here, 'generations': generations.copy()}
        occupied = set()
        for idx in sends_at[tick]:
            packet_id, _, code, jitter = sends[idx]
            src, dst, slot, delay, flight, rounds, hop, correction, a, b = cal.directions[code]
            if code // 2 not in cal.slice_sets[cal.slice_at[phase]]:
                statuses[idx] = 'not_in_slice'
            elif cal.blocked(phase, code):
                statuses[idx] = 'blackout'
            elif cal.margin(phase, code) < guard:
                statuses[idx] = 'guard'
            elif (src, slot) in occupied:
                statuses[idx] = 'port_busy'
            else:
                occupied.add((src, slot))
                if packet_id in lost:
                    statuses[idx] = 'lost'
                    continue
                statuses[idx] = 'sent'
                application = tick + rounds
                if application > r:
                    pending += 1
                    continue
                error, bound = errors[src], bounds[src]
                if error is not None:
                    signed_aging = (flight * t - delay) * actual[tick + flight - 1][dst]
                    for interval in range(tick + flight, application):
                        signed_aging += actual[interval][dst] * t
                    error += (bias[b] - bias[a]) * 1000000 + jitter - correction + signed_aging
                    bound += hop + cal.aging(phase, code)
                due[application].append((src, dst, generations[src], generations[dst], error, bound, packet_id))

    return {'status': 'ok', 'states': [query_states[tick] for tick in trace['queries']],
            'send_status': statuses, 'delivered': delivered, 'adopted': adopted,
            'unknown_payloads': unknown, 'stale_payloads': stale, 'pending': pending,
            'peak_known_abs_as': peak, 'always_known': always_known}
