"""Offline SyncWise exact-model JSON Lines entry point."""
import os
os.environ['OPENBLAS_NUM_THREADS'] = '1'
os.environ['OMP_NUM_THREADS'] = '1'
import json
import sys
from exactcal import calibrate
from exactplan import compile_plan, audit
from exactreplay import replay


def dispatch(request):
    op = request['op']
    if op == 'calibrate':
        return calibrate(request['profile'])
    if op == 'plan':
        return compile_plan(request['profile'], request['fabric'])
    if op == 'audit':
        return audit(request['profile'], request['fabric'], request['proposal'])
    return replay(request['profile'], request['fabric'], request['guard_ns'], request['trace'])


if __name__ == '__main__':
    for line in sys.stdin:
        if line.strip():
            response = dispatch(json.loads(line))
            print(json.dumps(response, separators=(',', ':'), allow_nan=False), flush=True)
